const docId = "system::heartbeat::pending-markdown";
const text = String(args.text || "").replace(/\s+/g, " ").trim();
if (!text) throw new Error("text is required");
const description = String(args.description || "").replace(/\s+/g, " ").trim();
if (!description) throw new Error("description is required");
const rawPriority = String(args.priority || "").trim().toLowerCase();
const priority = /^(low|medium|high)$/.test(rawPriority) ? rawPriority : "";
const meta = [];
if (priority) meta.push("priority:" + priority);
const suffix = meta.length ? ` [${meta.join(", ")}]` : "";
const workText = `${text} — ${description}`;
const db = await kernel.openDb();
const existing = await kernel.getByKey(db, kernel.stores.docs, docId);
const now = kernel.nowIso();
const base = "# Heartbeat Pending Items\n\n## Pending\n\n<!-- Add pending checklist items here -->\n\n## Completed\n\n<!-- Completed checklist items -->\n";
const markdown = String((existing && existing.text) || base);
const itemId = kernel.randomId("hb");
const line = `- [ ] (${itemId}) ${workText}${suffix}`;
let next = markdown;
if (next.includes("\n## Completed\n")) {
  next = next.replace(/\n## Completed\n/, `\n${line}\n\n## Completed\n`);
} else {
  next = `${next.trim()}\n\n## Pending\n\n${line}\n\n## Completed\n\n`;
}
const tx = db.transaction(kernel.stores.docs, "readwrite");
tx.objectStore(kernel.stores.docs).put({
  id: docId,
  scope: "system::heartbeat",
  title: "Heartbeat Pending Items",
  text: next,
  createdAt: (existing && existing.createdAt) || now,
  updatedAt: now
});
await kernel.txDone(tx);
return { ok: true, item: { id: itemId, text, description, priority: priority || null }, pendingCount: (next.match(/^- \[ \] \(([^)]+)\)\s*(.*)$/gm) || []).length };

const docId = "system::heartbeat::pending-markdown";
const db = await kernel.openDb();
const doc = await kernel.getByKey(db, kernel.stores.docs, docId);
const markdown = String((doc && doc.text) || "");
const pending = [...markdown.matchAll(/^- \[ \] \(([^)]+)\)\s*(.*)$/gm)].map((m) => ({ id: String(m[1] || "").trim(), text: String(m[2] || "").trim() }));
const completed = [...markdown.matchAll(/^- \[x\] \(([^)]+)\)\s*(.*)$/gim)].map((m) => ({ id: String(m[1] || "").trim(), text: String(m[2] || "").trim() }));
return { ok: true, pending, completedCount: completed.length, pendingCount: pending.length };

const docId = "system::heartbeat::pending-markdown";
const itemId = String(args.itemId || "").trim();
if (!itemId) throw new Error("itemId is required");
const esc = (v) => String(v).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const db = await kernel.openDb();
const existing = await kernel.getByKey(db, kernel.stores.docs, docId);
const markdown = String((existing && existing.text) || "");
const pendingPattern = new RegExp(`^- \\[ \\] \\(${esc(itemId)}\\)\\s*(.*)$`, "m");
const match = markdown.match(pendingPattern);
if (!match) throw new Error("Pending item not found");
const itemText = String(match[1] || "").trim();
const completedLine = `- [x] (${itemId}) ${itemText} (completed ${kernel.nowIso()})`;
let next = markdown.replace(pendingPattern, "").replace(/\n{3,}/g, "\n\n");
if (next.includes("\n## Completed\n")) {
  next = next.replace(/\n## Completed\n(?:\n)?/, `\n## Completed\n\n${completedLine}\n`);
} else {
  next = `${next.trim()}\n\n## Completed\n\n${completedLine}\n`;
}
const now = kernel.nowIso();
const tx = db.transaction(kernel.stores.docs, "readwrite");
tx.objectStore(kernel.stores.docs).put({
  id: docId,
  scope: "system::heartbeat",
  title: "Heartbeat Pending Items",
  text: next,
  createdAt: (existing && existing.createdAt) || now,
  updatedAt: now
});
await kernel.txDone(tx);
return { ok: true, itemId, text: itemText };

const query = kernel.normalizeText(args.query);
if (!query) throw new Error("query is required");
const topK = Math.max(1, Math.min(20, Number(args.topK || 5)));
const res = await fetch("/api/web/search", {
  method: "POST",
  headers: {
    "content-type": "application/json",
    accept: "application/json"
  },
  credentials: "same-origin",
  mode: "same-origin",
  body: JSON.stringify({ query, topK })
});
if (!res.ok) {
  let detail = "";
  try { detail = String(await res.text() || "").trim(); } catch {}
  throw new Error(`Web search request failed: ${res.status} ${res.statusText}${detail ? ` - ${detail}` : ""}`);
}
const payload = await res.json();
const items = Array.isArray(payload && payload.results) ? payload.results : [];
const out = items.slice(0, topK).map((item) => ({
  title: kernel.normalizeText((item && item.title) || ""),
  url: String((item && item.url) || "").trim(),
  snippet: kernel.normalizeText((item && item.snippet) || ""),
  source: String((item && item.source) || "duckduckgo")
})).filter((item) => item.url);
return {
  ok: true,
  query,
  count: out.length,
  results: out,
  source: String((payload && payload.source) || "backend_web_search"),
  fetchedAt: String((payload && payload.fetchedAt) || kernel.nowIso())
};

const path = String(args.path || "").trim();
if (!path) throw new Error("path is required");
const allowed = new Set(["AGENTS.md", "SOUL.md", "USER.md", "TOOLS.md"]);
if (!allowed.has(path)) throw new Error("path is not allowed");
const nav = (typeof self !== "undefined" && self.navigator) ? self.navigator : null;
if (!nav || !nav.storage || typeof nav.storage.getDirectory !== "function") throw new Error("OPFS is not supported in this runtime");
const root = await nav.storage.getDirectory();
const handle = await root.getFileHandle(path);
const file = await handle.getFile();
const text = await file.text();
return { ok: true, path, text, bytes: String(text).length };

