const path = String(args.path || "").trim();
if (!path) throw new Error("path is required");
const allowed = new Set(["AGENTS.md", "SOUL.md", "USER.md", "TOOLS.md"]);
if (!allowed.has(path)) throw new Error("path is not allowed");
const nav = (typeof self !== "undefined" && self.navigator) ? self.navigator : null;
if (!nav || !nav.storage || typeof nav.storage.getDirectory !== "function") throw new Error("OPFS is not supported in this runtime");
const appendText = args.append != null ? String(args.append) : "";
const prependText = args.prepend != null ? String(args.prepend) : "";
const find = args.find != null ? String(args.find) : "";
const replace = args.replace != null ? String(args.replace) : "";
if (!appendText && !prependText && !find) throw new Error("one of append, prepend, or find must be provided");
const root = await nav.storage.getDirectory();
const handle = await root.getFileHandle(path, { create: true });
const file = await handle.getFile();
const before = await file.text();
let after = before;
let replaced = 0;
if (prependText) after = prependText + after;
if (find) {
  if (!after.includes(find)) throw new Error("find text was not found");
  after = after.replace(find, replace);
  replaced = 1;
}
if (appendText) after = after + appendText;
const writer = await handle.createWritable();
await writer.write(after);
await writer.close();
return { ok: true, path, bytesBefore: before.length, bytesAfter: after.length, replaced, updatedAt: kernel.nowIso() };

const taskInput = (args && Object.prototype.hasOwnProperty.call(args, "task")) ? args.task : null;
if (taskInput == null || (typeof taskInput === "string" && !taskInput.trim())) throw new Error("task is required");
const task = (taskInput && typeof taskInput === "object") ? taskInput : String(taskInput).trim();
const targetAgent = String((args && args.targetAgent) || "").trim();
const intent = String((args && args.intent) || "").trim();
const tenantId = String((context && context.tenantId) || "tenant-dev");
const userId = String((context && context.userId) || "user-001");
const agentId = String((context && context.agentId) || "agent-main");
const body = { task: task, agentId: agentId };
if (targetAgent) body.targetAgent = targetAgent;
if (intent) body.intent = intent;
const res = await fetch("/api/agent/delegate", { method: "POST", headers: { "content-type": "application/json", accept: "application/json" }, credentials: "same-origin", mode: "same-origin", body: JSON.stringify(body) });
const data = await res.json().catch(() => ({}));
if (!res.ok) throw new Error(String((data && data.detail) || ("delegate_task failed: " + res.status)));
const delegationId = String((data && data.delegationId) || "").trim();
if (delegationId) {
  const now = String((data && data.createdAt) || kernel.nowIso());
  const scope = "a2a-delegations::" + tenantId + "::" + userId + "::" + agentId;
  const id = "a2a::delegation::" + delegationId;
  const record = {
    delegationId: delegationId,
    status: String((data && data.status) || "dispatched").toLowerCase(),
    targetAgent: String((data && data.targetAgent) || targetAgent || ""),
    fromAgent: agentId,
    task: (task && typeof task === "object") ? task : { text: String(task || "") },
    messages: [
      { status: "created", timestamp: now },
      { status: "dispatched", timestamp: now, messageId: String((data && data.messageId) || "") }
    ],
    result: null,
    error: null,
    createdAt: now,
    updatedAt: now
  };
  const db = await kernel.openDb();
  const tx = db.transaction(kernel.stores.docs, "readwrite");
  tx.objectStore(kernel.stores.docs).put({ id: id, scope: scope, kind: "a2a_delegation", title: "A2A Delegation " + delegationId.slice(0, 8), text: JSON.stringify(record, null, 2), ...record, createdAt: now, updatedAt: now });
  await kernel.txDone(tx);
}
return data;

