const params = new URLSearchParams();
const target = String((args && args.targetAgent) || "").trim();
const intent = String((args && args.intent) || "").trim();
const capabilities = Array.isArray(args && args.capabilities) ? args.capabilities.map((item) => String(item || "").trim()).filter(Boolean) : [];
if (target) params.set("targetAgent", target);
if (intent) params.set("intent", intent);
if (capabilities.length) params.set("capabilities", capabilities.join(","));
const query = params.toString();
const res = await fetch("/api/a2a/discovery/candidates" + (query ? ("?" + query) : ""), { method: "GET", headers: { accept: "application/json" }, credentials: "same-origin", mode: "same-origin" });
const data = await res.json().catch(() => ({}));
if (!res.ok) throw new Error(String((data && data.detail) || ("list_a2a_discovery_candidates failed: " + res.status)));
return data;
